'use client';

import { Portal } from '@ark-ui/react/portal';
import type { ToastOptions } from '@ark-ui/react/toast';
import {
  Toast as ToastPrimitive,
  Toaster as ToasterPrimitive,
  createToaster,
  useToastContext,
} from '@ark-ui/react/toast';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import type { OverlayPortalProps } from '@/lib/moduix/overlayPortal';
import { CloseButton } from '../close-button';
import { Spinner } from '../spinner';
import styles from './Toast.module.css';

type ToasterProps = Omit<ComponentProps<typeof ToasterPrimitive>, 'children'> &
  OverlayPortalProps & {
    children?: ComponentProps<typeof ToasterPrimitive>['children'];
  };

const ToastToaster = forwardRef<ComponentRef<typeof ToasterPrimitive>, ToasterProps>(
  function ToastToaster({ children, className, portalled = true, portalRef, ...props }, ref) {
    return (
      <Portal disabled={!portalled} container={portalRef}>
        <ToasterPrimitive
          ref={ref}
          className={clsx(styles.toaster, className)}
          {...props}
          data-slot="toast-toaster"
        >
          {children ?? ((toast) => <DefaultToast toast={toast} />)}
        </ToasterPrimitive>
      </Portal>
    );
  },
);

function DefaultToast({ toast }: { toast: ToastOptions }) {
  return (
    <Toast>
      {toast.title != null ? (
        <ToastTitle>
          {toast.type === 'loading' ? <Spinner decorative size="sm" /> : null}
          {toast.title}
        </ToastTitle>
      ) : null}
      {toast.description != null ? <ToastDescription /> : null}
      {toast.action ? <ToastActionTrigger>{toast.action.label}</ToastActionTrigger> : null}
      {toast.closable !== false ? <ToastCloseTrigger /> : null}
    </Toast>
  );
}

const Toast = forwardRef<
  ComponentRef<typeof ToastPrimitive.Root>,
  ComponentProps<typeof ToastPrimitive.Root>
>(function Toast({ className, ...props }, ref) {
  return (
    <ToastPrimitive.Root
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="toast-root"
    />
  );
});

const ToastTitle = forwardRef<
  ComponentRef<typeof ToastPrimitive.Title>,
  ComponentProps<typeof ToastPrimitive.Title>
>(function ToastTitle({ className, children, ...props }, ref) {
  const toast = useToastContext();

  return (
    <ToastPrimitive.Title
      ref={ref}
      className={clsx(styles.title, className)}
      {...props}
      data-slot="toast-title"
    >
      {children === undefined ? toast.title : children}
    </ToastPrimitive.Title>
  );
});

const ToastDescription = forwardRef<
  ComponentRef<typeof ToastPrimitive.Description>,
  ComponentProps<typeof ToastPrimitive.Description>
>(function ToastDescription({ className, children, ...props }, ref) {
  const toast = useToastContext();

  return (
    <ToastPrimitive.Description
      ref={ref}
      className={clsx(styles.description, className)}
      {...props}
      data-slot="toast-description"
    >
      {children === undefined ? toast.description : children}
    </ToastPrimitive.Description>
  );
});

const ToastActionTrigger = forwardRef<
  ComponentRef<typeof ToastPrimitive.ActionTrigger>,
  ComponentProps<typeof ToastPrimitive.ActionTrigger>
>(function ToastActionTrigger({ asChild, className, children, ...props }, ref) {
  return (
    <ToastPrimitive.ActionTrigger
      ref={ref}
      asChild={asChild}
      className={clsx(!asChild && styles.actionTrigger, className)}
      {...props}
      data-slot="toast-action-trigger"
    >
      {children}
    </ToastPrimitive.ActionTrigger>
  );
});

const ToastCloseTrigger = forwardRef<
  ComponentRef<typeof ToastPrimitive.CloseTrigger>,
  ComponentProps<typeof ToastPrimitive.CloseTrigger>
>(function ToastCloseTrigger(
  { asChild, className, children, 'aria-label': ariaLabel = a11yLabels.closeToast, ...props },
  ref,
) {
  if (asChild) {
    return (
      <ToastPrimitive.CloseTrigger
        ref={ref}
        asChild
        aria-label={ariaLabel}
        className={className}
        {...props}
        data-slot="toast-close-trigger"
      >
        {children}
      </ToastPrimitive.CloseTrigger>
    );
  }

  return (
    <ToastPrimitive.CloseTrigger asChild>
      <CloseButton
        ref={ref}
        aria-label={ariaLabel}
        className={clsx(styles.closeTrigger, className)}
        {...props}
        data-slot="toast-close-trigger"
      >
        {children}
      </CloseButton>
    </ToastPrimitive.CloseTrigger>
  );
});

const ToastContext = ToastPrimitive.Context;

export {
  Toast,
  ToastActionTrigger,
  ToastCloseTrigger,
  ToastContext,
  ToastDescription,
  ToastTitle,
  ToastToaster,
  createToaster,
  useToastContext,
};

export type {
  CreateToasterProps,
  CreateToasterReturn,
  ToastActionOptions,
  ToastActionTriggerProps,
  ToastCloseTriggerProps,
  ToastContextProps,
  ToastDescriptionProps,
  ToastOptions,
  ToastPlacement,
  ToastPromiseOptions,
  ToastRootProps,
  ToastStatus,
  ToastStatusChangeDetails,
  ToastTitleProps,
  ToastType,
  UseToastContext,
} from '@ark-ui/react/toast';
export type { ToasterProps };

@layer moduix.components {
  .root {
    --_toast-bg: var(--moduix-color-card);
    --_toast-border-color: var(--moduix-color-border);
    --_toast-color: var(--moduix-color-card-foreground);
    box-sizing: border-box;
    display: grid;
    width: 20rem;
    max-width: calc(100vw - var(--moduix-spacing-4) * 2);
    align-items: start;
    gap: var(--moduix-spacing-1);
    border: var(--moduix-border-width-sm) solid
      var(--moduix-toast-border-color, var(--_toast-border-color));
    border-radius: var(--moduix-radius-lg);
    background-color: var(--moduix-toast-bg, var(--_toast-bg));
    color: var(--moduix-toast-color, var(--_toast-color));
    background-clip: padding-box;
    box-shadow: var(--moduix-shadow-lg);
    padding: var(--moduix-spacing-4);
    translate: var(--x) var(--y);
    scale: var(--scale);
    z-index: var(--z-index);
    height: var(--height);
    opacity: var(--opacity);
    will-change: translate, opacity, scale;
    transition:
      translate var(--moduix-duration-slow),
      scale var(--moduix-duration-slow),
      opacity var(--moduix-duration-slow),
      height var(--moduix-duration-slow);
    transition-timing-function: cubic-bezier(0.21, 1.02, 0.73, 1);

    /* Room for the absolutely positioned close trigger. */
    &:has([data-slot='toast-close-trigger']) {
      padding-inline-end: calc(var(--moduix-spacing-4) + var(--moduix-spacing-7));
    }

    &[data-state='closed'] {
      transition:
        translate var(--moduix-duration-slow),
        scale var(--moduix-duration-slow),
        opacity var(--moduix-duration-normal);
      transition-timing-function: cubic-bezier(0.06, 0.71, 0.55, 1);
    }

    &[data-type='success'] {
      --_toast-bg: color-mix(
        in oklab,
        var(--moduix-color-success) 10%,
        var(--moduix-color-background)
      );
      --_toast-border-color: color-mix(in oklab, var(--moduix-color-success) 34%, transparent);
      --_toast-color: var(--moduix-color-foreground);
    }

    &[data-type='warning'] {
      --_toast-bg: color-mix(
        in oklab,
        var(--moduix-color-warning) 13%,
        var(--moduix-color-background)
      );
      --_toast-border-color: color-mix(in oklab, var(--moduix-color-warning) 38%, transparent);
      --_toast-color: var(--moduix-color-foreground);
    }

    &[data-type='error'] {
      --_toast-bg: color-mix(
        in oklab,
        var(--moduix-color-destructive) 9%,
        var(--moduix-color-background)
      );
      --_toast-border-color: color-mix(in oklab, var(--moduix-color-destructive) 35%, transparent);
      --_toast-color: var(--moduix-color-foreground);
    }
  }

  .title {
    display: flex;
    min-width: 0;
    align-items: center;
    gap: var(--moduix-spacing-2);
    margin: 0;
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-sm);
    overflow-wrap: anywhere;
  }

  .description {
    margin: 0;
    min-width: 0;
    color: var(--moduix-toast-description-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    overflow-wrap: anywhere;
  }

  .actionTrigger {
    display: inline-flex;
    width: max-content;
    max-width: 100%;
    min-width: 0;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-spacing-2);
    min-height: var(--moduix-size-xs);
    margin-block-start: var(--moduix-spacing-2);
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-sm);
    background: transparent;
    color: var(--moduix-color-foreground);
    padding: var(--moduix-spacing-1) var(--moduix-spacing-2);
    font: inherit;
    font-size: var(--moduix-text-xs);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-xs);
    cursor: pointer;
    text-align: start;
    user-select: none;
    overflow-wrap: anywhere;
    transition: background-color var(--moduix-transition-default);

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-color-accent);
      }
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: 0;
    }
  }

  .closeTrigger {
    position: absolute;
    inset-block-start: var(--moduix-spacing-2);
    inset-inline-end: var(--moduix-spacing-2);
  }

  @media (max-width: 40rem) {
    .toaster {
      width: calc(
        100vw - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px) -
          var(--viewport-offset-left) - var(--viewport-offset-right)
      );
    }

    .root {
      inset-inline: 0;
      margin-inline: auto;
      max-width: 100%;
    }
  }
}
